-- B7 review package only: execution requires the matching explicit approval.
SELECT User,Host FROM mysql.user WHERE User IN ('taskcompass_phase12_test','taskcompass_phase12_restore') ORDER BY User,Host;
SELECT GRANTEE,PRIVILEGE_TYPE,IS_GRANTABLE FROM information_schema.USER_PRIVILEGES WHERE GRANTEE IN (CONCAT(CHAR(39),'taskcompass_phase12_test',CHAR(39),'@',CHAR(39),'127.0.0.1',CHAR(39)),CONCAT(CHAR(39),'taskcompass_phase12_restore',CHAR(39),'@',CHAR(39),'127.0.0.1',CHAR(39))) ORDER BY GRANTEE,PRIVILEGE_TYPE,IS_GRANTABLE;
SELECT GRANTEE,TABLE_SCHEMA,PRIVILEGE_TYPE,IS_GRANTABLE FROM information_schema.SCHEMA_PRIVILEGES WHERE GRANTEE IN (CONCAT(CHAR(39),'taskcompass_phase12_test',CHAR(39),'@',CHAR(39),'127.0.0.1',CHAR(39)),CONCAT(CHAR(39),'taskcompass_phase12_restore',CHAR(39),'@',CHAR(39),'127.0.0.1',CHAR(39))) ORDER BY GRANTEE,TABLE_SCHEMA,PRIVILEGE_TYPE,IS_GRANTABLE;
SELECT GRANTEE,TABLE_SCHEMA,TABLE_NAME,PRIVILEGE_TYPE,IS_GRANTABLE FROM information_schema.TABLE_PRIVILEGES WHERE GRANTEE IN (CONCAT(CHAR(39),'taskcompass_phase12_test',CHAR(39),'@',CHAR(39),'127.0.0.1',CHAR(39)),CONCAT(CHAR(39),'taskcompass_phase12_restore',CHAR(39),'@',CHAR(39),'127.0.0.1',CHAR(39))) ORDER BY GRANTEE,TABLE_SCHEMA,TABLE_NAME,PRIVILEGE_TYPE,IS_GRANTABLE;
SELECT GRANTEE,TABLE_SCHEMA,TABLE_NAME,COLUMN_NAME,PRIVILEGE_TYPE,IS_GRANTABLE FROM information_schema.COLUMN_PRIVILEGES WHERE GRANTEE IN (CONCAT(CHAR(39),'taskcompass_phase12_test',CHAR(39),'@',CHAR(39),'127.0.0.1',CHAR(39)),CONCAT(CHAR(39),'taskcompass_phase12_restore',CHAR(39),'@',CHAR(39),'127.0.0.1',CHAR(39))) ORDER BY GRANTEE,TABLE_SCHEMA,TABLE_NAME,COLUMN_NAME,PRIVILEGE_TYPE,IS_GRANTABLE;
SELECT Host,User,Role,Admin_option FROM mysql.roles_mapping WHERE User IN ('taskcompass_phase12_test','taskcompass_phase12_restore') ORDER BY User,Host,Role;
